/**
 * NoorDeen — Thematic Verse Index (Phase 2)
 *
 * Renders public/data/tafsir/themes.json as a searchable finding aid inside
 * quran.html. The index is generated by scripts/build-thematic-index.cjs from
 * word-boundary keyword matches over the bundled English translation.
 *
 * It is deliberately labelled as a finding aid, not a scholarly thematic
 * classification, and it never presents keyword hits as tafsir.
 */
(function (global) {
  'use strict';

  var dataPromise = null;
  var themes = [];
  var activeThemeId = null;
  var elements = null;
  var searchValue = '';
  var eventsBound = false;

  function resolve(path) {
    if (global.App && typeof global.App.resolveUrl === 'function') {
      return global.App.resolveUrl(path);
    }
    return path;
  }

  function escapeHtml(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function surahName(number) {
    var list = (global.ISLAMIC_DATA && global.ISLAMIC_DATA.surahs) || [];
    for (var i = 0; i < list.length; i += 1) {
      if (list[i].number === number) return list[i].englishName || ('Surah ' + number);
    }
    return 'Surah ' + number;
  }

  function load() {
    if (dataPromise) return dataPromise;
    dataPromise = fetch(resolve('data/tafsir/themes.json'), { credentials: 'same-origin' })
      .then(function (response) {
        if (!response.ok) throw new Error('HTTP ' + response.status);
        return response.json();
      })
      .then(function (data) {
        if (!data || !Array.isArray(data.themes) || data.themes.length === 0) {
          throw new Error('Invalid themes.json');
        }
        themes = data.themes;
        return data;
      })
      .catch(function (error) {
        dataPromise = null;
        throw error;
      });
    return dataPromise;
  }

  function renderChips() {
    if (!elements || !elements.list) return;
    var query = searchValue.trim().toLowerCase();
    var filtered = themes.filter(function (theme) {
      if (!query) return true;
      var haystack = [theme.id, theme.title, theme.description].concat(theme.keywords || []).join(' ').toLowerCase();
      return haystack.indexOf(query) !== -1;
    });

    if (filtered.length === 0) {
      elements.list.innerHTML = '<p style="margin: 0; font-size: 0.88rem; color: var(--color-text-muted);">No theme matches that search.</p>';
      return;
    }

    elements.list.innerHTML = filtered.map(function (theme) {
      var active = theme.id === activeThemeId;
      return '<button type="button" role="listitem" class="btn ' + (active ? 'btn-primary' : 'btn-outline') + '" ' +
        'data-theme="' + escapeHtml(theme.id) + '" aria-pressed="' + (active ? 'true' : 'false') + '" ' +
        'style="padding: 5px 11px; font-size: 0.82rem;">' +
        escapeHtml(theme.title) +
        ' <span style="opacity: 0.75; font-size: 0.75rem;">' + theme.totalVerses + '</span>' +
        '</button>';
    }).join('');
  }

  function renderResults(theme) {
    if (!elements || !elements.results) return;
    if (!theme) {
      elements.results.innerHTML = '<p style="margin: 0; color: var(--color-text-muted);">Choose a theme to see matching verses.</p>';
      return;
    }

    var rows = theme.verses.map(function (ref) {
      var name = surahName(ref.s);
      var href = resolve('quran.html?surah=' + ref.s + '&ayah=' + ref.a);
      return '<li style="margin-bottom: 10px;">' +
        '<a href="' + escapeHtml(href) + '" style="font-weight: 700; color: var(--color-primary); text-decoration: none;">' +
        escapeHtml(name) + ' ' + ref.s + ':' + ref.a + '</a>' +
        '<div style="font-size: 0.88rem; color: var(--color-text-muted); line-height: 1.6;">' + escapeHtml(ref.t) + '</div>' +
        '</li>';
    }).join('');

    var truncation = theme.truncated
      ? '<p style="margin: 8px 0 0; font-size: 0.82rem; color: var(--color-gold-dark); font-weight: 600;">Showing the first ' +
        theme.shownVerses + ' of ' + theme.totalVerses + ' matching verses. Refine with the search box or read the full surah for context.</p>'
      : '';

    elements.results.innerHTML =
      '<div style="display: flex; justify-content: space-between; align-items: baseline; gap: 10px; flex-wrap: wrap;">' +
      '<h3 style="margin: 0; font-family: var(--font-heading); font-size: 1.1rem; color: var(--color-primary);">' + escapeHtml(theme.title) + '</h3>' +
      '<span class="badge" style="background: var(--color-surface); color: var(--color-gold-dark); font-size: 0.74rem;">' +
      theme.totalVerses + ' matching verses</span>' +
      '</div>' +
      '<p style="margin: 6px 0 0; font-size: 0.9rem; color: var(--color-text-muted);">' + escapeHtml(theme.description) + '</p>' +
      truncation +
      '<ol style="margin: 14px 0 0; padding-left: 22px;">' + rows + '</ol>' +
      '<p style="margin: 12px 0 0; font-size: 0.78rem; color: var(--color-text-muted);"><strong>Keywords used:</strong> ' +
      (theme.keywords || []).map(escapeHtml).join(', ') + '</p>';
  }

  function selectTheme(id) {
    var theme = null;
    for (var i = 0; i < themes.length; i += 1) {
      if (themes[i].id === id) {
        theme = themes[i];
        break;
      }
    }
    if (!theme) return false;
    activeThemeId = theme.id;
    renderChips();
    renderResults(theme);
    return true;
  }

  function bindEvents() {
    if (!elements || eventsBound) return;
    eventsBound = true;
    if (elements.search) {
      elements.search.addEventListener('input', function () {
        searchValue = elements.search.value || '';
        renderChips();
      });
    }
    if (elements.list) {
      elements.list.addEventListener('click', function (event) {
        var target = event.target;
        while (target && target !== elements.list) {
          if (target.getAttribute && target.getAttribute('data-theme')) {
            selectTheme(target.getAttribute('data-theme'));
            return;
          }
          target = target.parentNode;
        }
      });
    }
  }

  function init() {
    var root = document.getElementById('thematic-index');
    if (!root) return;

    elements = {
      root: root,
      list: document.getElementById('thematic-theme-list'),
      results: document.getElementById('thematic-results'),
      search: document.getElementById('thematic-search'),
      count: document.getElementById('thematic-index-count'),
      disclaimer: document.getElementById('thematic-disclaimer')
    };

    bindEvents();

    load().then(function (data) {
      if (elements.count) {
        var totalAyahs = data.corpus && data.corpus.totalAyahs ? data.corpus.totalAyahs.toLocaleString() : '6,236';
        elements.count.textContent = data.themes.length + ' themes • ' + totalAyahs + ' verses indexed';
      }
      if (elements.disclaimer && data.disclaimer) elements.disclaimer.textContent = data.disclaimer;
      renderChips();

      var requested = null;
      try {
        requested = new URLSearchParams(global.location.search).get('theme');
      } catch (error) {
        requested = null;
      }
      if (!requested || !selectTheme(requested)) renderResults(null);
    }).catch(function (error) {
      console.warn('[ThematicIndex] Could not load themes:', error.message);
      if (elements.count) elements.count.textContent = 'Thematic index unavailable';
      if (elements.results) {
        elements.results.innerHTML =
          '<p style="margin: 0; line-height: 1.7;"><strong>The thematic index could not be loaded.</strong> It is fetched on demand and may not be cached yet. Check your connection and try again.</p>' +
          '<button type="button" class="btn btn-outline" style="margin-top: 10px; padding: 5px 12px; font-size: 0.82rem;" onclick="window.ThematicIndex.init()">Retry loading themes</button>';
      }
    });
  }

  if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', init);
    } else {
      init();
    }
  }

  global.ThematicIndex = {
    init: init,
    load: load,
    selectTheme: selectTheme
  };
})(typeof window !== 'undefined' ? window : globalThis);
